// Authentication is delegated to the Supabase callbacks supplied by the parent.

import React, { useEffect, useState } from "react";

const svgProps = {
  width: 24,
  height: 24,
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 2,
  strokeLinecap: "round",
  strokeLinejoin: "round",
  "aria-hidden": true,
};
const Eye = () => (
  <svg {...svgProps}>
    <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);
const EyeOff = () => (
  <svg {...svgProps}>
    <path d="M10.7 5.1A10 10 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-2.2 3.2M6.6 6.6A17 17 0 0 0 2 12s3.5 7 10 7a10 10 0 0 0 5.4-1.6" />
    <path d="M9.9 9.9a3 3 0 0 0 4.2 4.2" />
    <path d="m2 2 20 20" />
  </svg>
);
const Check = () => (
  <svg {...svgProps}>
    <path d="M20 6 9 17l-5-5" />
  </svg>
);
const CircleAlert = () => (
  <svg {...svgProps}>
    <circle cx="12" cy="12" r="10" />
    <path d="M12 8v4M12 16h.01" />
  </svg>
);

const LOGO =
  "data:image/png;base64,";

const ACCOUNT_STYLES = `
.account-page, .account-dialog, .account-dialog-overlay {
  --radius: 0.5rem;
  --background: oklch(0.96 0.025 350);
  --foreground: oklch(0.25 0.035 350);
  --card: oklch(0.998 0.002 350);
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.29 0.035 350);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.945 0.037 350);
  --secondary-foreground: var(--foreground);
  --muted: oklch(0.96 0.02 350);
  --muted-foreground: oklch(0.55 0.025 350);
  --accent: oklch(0.9 0.055 350);
  --accent-foreground: var(--foreground);
  --destructive: oklch(0.51 0.17 20);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.91 0.026 350);
  --input: var(--border);
  --ring: oklch(0.7 0.14 350);
  --brand: oklch(0.62 0.16 350);
  --overlay: oklch(0.25 0.035 350 / 35%);
  --account-shadow: 0 16px 64px oklch(0.55 0.07 350 / 9%);
  --font-sans: "DM Sans", sans-serif;
}


.account-page *, .account-dialog * { box-sizing: border-box; }
.account-page button, .account-dialog button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; cursor: pointer; border: 0; font-family: inherit; transition: background 150ms; }
.account-page button:focus-visible, .account-dialog button:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
.account-dialog { font-family: "DM Sans", Arial, sans-serif; color: var(--foreground); }
.account-reveal svg { width: 16px; height: 16px; }
.account-dialog-mark svg { width: 24px; height: 24px; }
.account-page { box-sizing: border-box; background: var(--background); color: var(--foreground); font-family: "DM Sans", Arial, sans-serif; letter-spacing: 0; min-height: 100svh; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: max(12px, env(safe-area-inset-top, 0px)) 12px max(12px, env(safe-area-inset-bottom, 0px)); }
.account-card { width: 100%; max-width: 440px; background: var(--card); border: 1px solid var(--border); border-radius: 28px; padding: 32px 30px 26px; box-shadow: var(--account-shadow); }
.account-header { text-align: center; }
.account-header h1 { font-size: 30px; line-height: 1.25; font-weight: 700; margin: 0 0 18px; }
.account-logo { width: 112px; height: 112px; border-radius: 25px; margin: 0 auto 14px; }
.account-subtitle { font-size: 14px; color: var(--muted-foreground); margin: 0 0 24px; }
.account-form { display: flex; flex-direction: column; gap: 17px; }
.account-field label { display: block; font-size: 14px; font-weight: 600; margin: 0 0 8px 3px; }
.account-input-wrap { position: relative; }
.account-input { width: 100%; height: 50px; border: 1px solid transparent; background: var(--secondary); border-radius: 25px; padding: 0 19px; color: var(--foreground); font-family: inherit; font-size: 15px; outline: none; transition: border-color 150ms; }
.account-input::placeholder { color: var(--muted-foreground); }
.account-input:focus { border-color: var(--ring); }
.account-input[aria-invalid="true"] { border-color: var(--destructive); }
.account-password { padding-right: 52px; }
.account-reveal { position: absolute; right: 8px; top: 5px; height: 37px; width: 37px; padding: 0; border-radius: 50%; color: var(--muted-foreground); background: transparent; }
.account-reveal:hover { color: var(--foreground); background: var(--accent); }
.account-submit { border-radius: 26px; min-height: 52px; width: 100%; background: var(--primary); color: var(--primary-foreground); font-size: 16px; font-weight: 600; }
.account-submit:hover { background: var(--foreground); }
.account-switch { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 4px; margin: 22px 0 0; font-size: 14px; color: var(--muted-foreground); }
.account-text-button { color: var(--brand); background: transparent; height: auto; padding: 4px 2px; font-size: inherit; font-weight: 700; }
.account-text-button:hover { text-decoration: underline; }
.account-error { color: var(--destructive); font-size: 12px; margin: -3px 3px 0; }
.account-dialog-overlay { position: fixed; inset: 0; z-index: 50; background: var(--overlay); backdrop-filter: blur(3px); }
.account-dialog { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: calc(100% - 40px); max-width: 360px; border-radius: 24px; background: var(--card); padding: 30px; z-index: 51; box-shadow: var(--account-shadow); text-align: center; }
.account-dialog-mark { width: 48px; height: 48px; display: grid; place-items: center; margin: 0 auto 18px; border-radius: 50%; background: var(--secondary); color: var(--brand); }
.account-dialog-title { font-size: 21px; font-weight: 700; margin: 0 0 12px; }
.account-dialog-description { font-size: 14px; line-height: 1.6; color: var(--muted-foreground); margin: 0 0 22px; }
@media (max-width: 480px) {
  .account-card { padding: 28px 22px 24px; }
}
@media (max-height: 720px) {
  .account-page { justify-content: flex-start; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

`;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateAccount(mode, fields) {
  const required =
    mode === "register"
      ? [fields.fullName, fields.age, fields.contact, fields.password]
      : [fields.contact, fields.password];
  if (required.some((value) => !value.trim()))
    return { valid: false, message: "Please fill in all required fields." };
  const contact = fields.contact.trim();
  if (contact.length > 255 || !EMAIL_PATTERN.test(contact))
    return { valid: false, message: "Enter a valid email address." };
  if (mode === "register" && fields.password.length < 6)
    return { valid: false, message: "Password must be at least 6 characters." };
  if (fields.password.length > 128)
    return { valid: false, message: "Password is too long." };
  if (mode === "register") {
    if (fields.fullName.trim().length > 100)
      return { valid: false, message: "Name is too long." };
    const age = Number(fields.age);
    if (!/^\d{1,3}$/.test(fields.age.trim()) || age < 1 || age > 120)
      return { valid: false, message: "Enter a valid age." };
  }
  return { valid: true, message: "" };
}

function Notice({ notice, onClose }) {
  useEffect(() => {
    if (!notice) return undefined;
    const onKey = (event) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [notice, onClose]);
  if (!notice) return null;
  return (
    <>
      <div className="account-dialog-overlay" onClick={onClose} />
      <div
        className="account-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="account-dialog-title"
        aria-describedby="account-dialog-text"
      >
        <div className="account-dialog-mark">
          {notice.valid ? <Check /> : <CircleAlert />}
        </div>
        <h2 id="account-dialog-title" className="account-dialog-title">
          {notice.title}
        </h2>
        <p id="account-dialog-text" className="account-dialog-description">
          {notice.message}
        </p>
        <Button variant="account" type="button" autoFocus onClick={onClose}>
          {notice.valid ? "Got it" : "OK"}
        </Button>
      </div>
    </>
  );
}
function Button({ variant = "account", className = "", children, ...props }) {
  const variants = {
    account: "account-submit",
    social: "account-social",
    text: "account-text-button",
    reveal: "account-reveal",
  };
  return (
    <button className={`${variants[variant] || ""} ${className}`} {...props}>
      {children}
    </button>
  );
}

function SignInPage({ onSignIn, onRegister }) {
  const [mode, setMode] = useState("login");
  const [fields, setFields] = useState({
    fullName: "",
    age: "",
    contact: "",
    password: "",
  });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const registering = mode === "register";
  const update = (key, value) => {
    setFields((current) => ({ ...current, [key]: value }));
    setError("");
  };
  async function submit(event) {
    event.preventDefault();
    const result = validateAccount(mode, fields);
    setError(result.message);
    if (!result.valid) return;

    const callback = registering ? onRegister : onSignIn;
    if (typeof callback !== "function") {
      setError("Supabase authentication is not available. Please try again later.");
      return;
    }

    setIsSubmitting(true);
    try {
      await callback({
        fullName: fields.fullName.trim(),
        age: fields.age,
        contact: fields.contact.trim(),
        password: fields.password,
      });

      if (registering) {
        const isAdminEmail = fields.contact.trim().toLowerCase() === "joannmoico20@gmail.com";
        setMode("login");
        setFields({
          fullName: "",
          age: "",
          contact: fields.contact.trim(),
          password: "",
        });
        setNotice({
          title: "Check your email",
          message: isAdminEmail
            ? "Your admin account was created. Confirm your email, then log in. This address is automatically approved as the admin account."
            : "Your account was created. Confirm your email, then wait for coordinator approval before logging in.",
          valid: true,
        });
      }
    } catch (authError) {
      setError(authError.message || "Could not authenticate with Supabase.");
    } finally {
      setIsSubmitting(false);
    }
  }
  function switchMode() {
    setMode(registering ? "login" : "register");
    setError("");
    setFields({ fullName: "", age: "", contact: "", password: "" });
    setShowPassword(false);
  }

  return (
    <main className="account-page">
      <style>{ACCOUNT_STYLES}</style>
      <section
        className="account-card"
        aria-label={registering ? "Create account" : "Log in"}
      >
        <header className="account-header">
          <h1>{registering ? "Create Account" : "Welcome Back"}</h1>
          <img
            className="account-logo"
            src={LOGO}
            alt="NutriGrid"
            width="104"
            height="104"
          />
          <p className="account-subtitle">
            {registering
              ? "A little step toward a healthier community."
              : "Good to see you again."}
          </p>
        </header>
        <form className="account-form" onSubmit={submit} noValidate>
          {registering && (
            <>
              <div className="account-field">
                <label htmlFor="fullName">Full name</label>
                <input
                  className="account-input"
                  id="fullName"
                  autoComplete="name"
                  placeholder="Your full name"
                  maxLength={100}
                  value={fields.fullName}
                  onChange={(e) => update("fullName", e.target.value)}
                  aria-required="true"
                  aria-invalid={!!error && !fields.fullName.trim()}
                />
              </div>
              <div className="account-field">
                <label htmlFor="age">Age</label>
                <input
                  className="account-input"
                  id="age"
                  type="text"
                  inputMode="numeric"
                  placeholder="Your age"
                  maxLength={3}
                  value={fields.age}
                  onChange={(e) => update("age", e.target.value)}
                  aria-required="true"
                  aria-invalid={!!error && !fields.age.trim()}
                />
              </div>
            </>
          )}
          <div className="account-field">
            <label htmlFor="contact">Email address</label>
            <input
              className="account-input"
              id="contact"
              type="email"
              autoComplete="username"
              placeholder="Email address"
              maxLength={255}
              value={fields.contact}
              onChange={(e) => update("contact", e.target.value)}
              aria-required="true"
              aria-invalid={!!error && !fields.contact.trim()}
            />
          </div>
          <div className="account-field">
            <label htmlFor="password">Password</label>
            <div className="account-input-wrap">
              <input
                className="account-input account-password"
                id="password"
                type={showPassword ? "text" : "password"}
                autoComplete={registering ? "new-password" : "current-password"}
                placeholder="Enter your password"
                maxLength={128}
                value={fields.password}
                onChange={(e) => update("password", e.target.value)}
                aria-required="true"
                aria-invalid={!!error && !fields.password.trim()}
              />
              <Button
                variant="reveal"
                type="button"
                title={showPassword ? "Hide password" : "Show password"}
                aria-label={showPassword ? "Hide password" : "Show password"}
                onClick={() => setShowPassword(!showPassword)}
              >
                {showPassword ? <EyeOff /> : <Eye />}
              </Button>
            </div>
          </div>
          {error && (
            <p className="account-error" role="alert">
              {error}
            </p>
          )}
          <Button variant="account" type="submit" disabled={isSubmitting}>
            {isSubmitting
              ? "Please wait..."
              : registering
                ? "Create account"
                : "Log in"}
          </Button>
        </form>
        <p className="account-switch">
          {registering ? "Already have an account?" : "Don't have an account?"}
          <Button variant="text" type="button" onClick={switchMode}>
            {registering ? "Log in" : "Create account"}
          </Button>
        </p>
      </section>
      <Notice notice={notice} onClose={() => setNotice(null)} />
    </main>
  );
}

export default SignInPage;